import hashlib

def key_of(ins, arg, ctx):
    if ins in ("COPY", "ADD"):
        src = arg.split()[0]
        if src in (".", "./", "*"):
            files = sorted(ctx)
        elif src.endswith("/"):
            files = sorted(p for p in ctx if p.startswith(src.rstrip("/") + "/"))
        else:
            files = [src] if src in ctx else []
        h = hashlib.sha256()
        for p in files:
            h.update(p.encode()); h.update(b"="); h.update(ctx[p].encode()); h.update(b"\n")
        return ins + ":" + h.hexdigest()
    return ins + ":" + arg

def min_rebuild_layers(instructions, before, after):
    parent_ok = True
    for idx, (ins, arg) in enumerate(instructions, 1):
        ok = parent_ok and key_of(ins, arg, after) == key_of(ins, arg, before)
        if not ok:
            return idx, len(instructions) - idx + 1   # 该层及其后全部重建
    return None, 0

